{
  "name": "opencode-session-time",
  "version": "0.4.0",
  "description": "OpenCode V2 TUI plugin: current-turn stopwatch, Session Timings sidebar, and a searchable /time timeline popup with per-turn details.",
  "author": "LazyGatto",
  "contributors": [
    "Ran Sagy (https://github.com/ransagy)"
  ],
  "homepage": "https://github.com/LazyGatto/opencode-session-time#readme",
  "bugs": {
    "url": "https://github.com/LazyGatto/opencode-session-time/issues"
  },
  "type": "module",
  "exports": {
    "./tui": "./src/tui.tsx"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "timestamp",
    "session"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/LazyGatto/opencode-session-time.git"
  },
  "dependencies": {
    "@opencode/plugin": "latest"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.8",
    "@opentui/solid": ">=0.5.8",
    "solid-js": ">=1.9.0"
  }
}
